<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/LinkChecker.php';require_once __DIR__.'/../core/Json.php';use Core\CacheStore;use Core\LinkChecker;$a=array_slice(isset($argv)?$argv:array(),1);$b=false;$c=array('limit'=>40,'budget'=>20,'stale'=>360,'pan'=>'','dry'=>false,);$d='';$e=0;$f=count($a);while($e<$f){$g=(string)$a[$e];if($g==='--help'||$g==='-h'){echo"php cron/link_check.php [--limit N] [--budget N] [--stale N] [--pan quark,uc] [--dry] [--quiet]\n";exit(0);}if($g==='--quiet'||$g==='-q'){$c['quiet']=true;$b=true;$e++;continue;}if($g==='--dry'){$c['dry']=true;$e++;continue;}if(strpos($g,'--')!==0){$d='无法识别的参数：'.$g;break;}$h=strpos($g,'=');if($h!==false){$i=substr($g,2,$h-2);$j=substr($g,$h+1);$e++;}else{$i=substr($g,2);if(!in_array($i,array('limit','budget','stale','pan'),true)){$d='未知参数：'.$g;break;}if($e+1>=$f||strpos((string)$a[$e+1],'--')===0){$d='参数缺少值：'.$g;break;}$j=$a[$e+1];$e+=2;}if($i==='limit'||$i==='budget'||$i==='stale'){$c[$i]=(int)$j;}elseif($i==='pan'){$c[$i]=strtolower(trim((string)$j));}else{$d='未知参数：--'.$i;break;}}if($d!==''){fwrite(STDERR,$d."\n");exit(1);}if($c['limit']<1||$c['limit']>200){fwrite(STDERR,"--limit 范围必须是 1~200。\n");exit(1);}if($c['budget']<5||$c['budget']>300){fwrite(STDERR,"--budget 范围必须是 5~300 秒。\n");exit(1);}if($c['stale']<0){fwrite(STDERR,"--stale 不能为负数。\n");exit(1);}$k=time();$l=0;$m=0;$n=0;$o=0;$p=CacheStore::itemsWithLinks($c['limit']);if(!$p&&!$b){echo"没有待检测的条目（download_url 全部为空，或都已在本轮预算内检查过）。\n";}foreach($p as $q){if($l>0&&(time()-$k)>=$c['budget']){break;}$r=(string)$q['download_url'];$s=array();if(strpos($r,'[')===0){$t=json_decode($r,true);if(is_array($t)){foreach($t as $u){if(is_array($u)&&!empty($u['url'])){$s[]=array('label'=>(isset($u['label'])?$u['label']:'下载'),'url'=>(string)$u['url']);}elseif(is_string($u)&&$u!==''){$s[]=array('label'=>'下载','url'=>$u);}}}}else{foreach(preg_split('/\r?\n/',$r)as $v){$v=trim($v);if($v!==''){$s[]=array('label'=>'下载','url'=>$v);}}}if(!$s){continue;}$w=array();foreach($s as $x){$y=trim((string)$x['url']);if($y===''){continue;}$z=LinkChecker::check($y);if($c['pan']!==''&&!in_array($z['pan'],array_map('trim',explode(',',$c['pan'])),true)){continue;}$w[]=array('label'=>(string)$x['label'],'url'=>$y,'ok'=>(bool)$z['ok'],'code'=>(int)$z['code'],'msg'=>(string)$z['msg'],);if(!empty($z['ok'])){$m++;}else{$n++;}}$l++;if(!$w){continue;}if($c['dry']){if(!$b){echo sprintf("[dry] #%d %s → 有效 %d / 失效 %d\n",(int)$q['id'],(string)$q['download_url'],count(array_filter($w,function($a){return!empty($a['ok']);})),count(array_filter($w,function($a){return empty($a['ok']);})));}continue;}try{CacheStore::saveLinkChecks((int)$q['id'],$w);}catch(\Throwable $b1){$o++;if(!$b){fwrite(STDERR,"[warn] save failed for item #$a1: ".$b1->getMessage()."\n");}}}$c1=CacheStore::countPendingLinkChecks(max(1,(int)floor($c['stale']/60)));if($b){echo sprintf("link_check: checked=%d ok=%d dead=%d fail=%d remaining=%d elapsed=%ds dry=%s\n",$l,$m,$n,$o,$c1,(time()-$k),$c['dry']?'1':'0');}else{echo"============================================\n";echo"媒资资料库 · 链接失效检测\n";echo"--------------------------------------------\n";echo"检测条目数 : {$l}\n";echo"链接有效   : {$m}\n";echo"链接失效   : {$n}\n";echo"保存失败   : {$o}\n";echo"仍有待检   : {$c1}\n";echo"耗时       : ".(time()-$k)." 秒\n";echo"模式       : ".($c['dry']?'只读（--dry）':'已写库')."\n";if($c['pan']!==''){echo"网盘过滤   : ".$c['pan']."\n";}echo"============================================\n";echo"提示：失效条目可在后台「条目匹配 → 已匹配」页按状态筛选查看。\n";}exit($o>$l&&$l>0?1:0);